(* Convert bundled icon JSON into immutable native children during the build. *)

let emit_children out children =
  output_char out '[';
  List.iter (function
    | `List [`String tag; `Assoc attrs] ->
        Printf.fprintf out "(%S,[" tag;
        List.iter (function
          | name,`String value -> Printf.fprintf out "(%S,%S);" name value
          | _ -> invalid_arg "Bundled icon attributes must be strings") attrs;
        output_string out "]);"
    | _ -> invalid_arg "Bundled icon children must contain a tag and attributes") children;
  output_char out ']'

let generate source destination =
  let entries = match Yojson.Safe.from_file source with
    | `Assoc entries -> entries
    | _ -> invalid_arg "Bundled icon table must be an object" in
  let unique = Hashtbl.create (List.length entries) in
  List.iter (fun (name,value) ->
    match value with
    | `List children -> Hashtbl.replace unique name children
    | _ -> invalid_arg ("Bundled icon must be an array: " ^ name)) entries;
  let entries = List.sort (fun (a,_) (b,_) -> String.compare a b)
    (List.of_seq (Hashtbl.to_seq unique)) in
  Out_channel.with_open_bin destination (fun out ->
    output_string out "(* Generated by tools/icon_gen.exe; do not edit. *)\n\n";
    output_string out "let table : (string * Icon_tabler_data.children) array = [|\n";
    List.iter (fun (name,children) ->
      Printf.fprintf out "  (%S," name;
      emit_children out children;
      output_string out ");\n") entries;
    output_string out "|]\n")

let () = match Sys.argv with
  | [|_; source; destination|] -> generate source destination
  | _ -> invalid_arg "Usage: icon_gen.exe ICON_JSON OUTPUT_ML"
